{"command":"set -euo pipefail
REPO='edburns/edburns-dd-3068633-linux-x64-03'; PR=4; REVIEW_ID=5304826134; EXPECTED_HEAD='aed95343f4bfdfa580d95e37bec781dc205fbd05'; BASE='experiment/shepherd-control'
[ "$BASE" != main ] || { echo "ERROR: BASE_BRANCH must never be 'main'."; exit 1; }
PR_JSON=$(gh pr view "$PR" -R "$REPO" --json state,isDraft,baseRefName,headRefOid,mergeable,statusCheckRollup)
printf '%s' "$PR_JSON" | jq -e --arg head "$EXPECTED_HEAD" --arg base "$BASE" '.state == "OPEN" and .isDraft == false and .headRefOid == $head and .baseRefName == $base and .mergeable != "CONFLICTING"' >/dev/null
BAD_CHECKS=$(printf '%s' "$PR_JSON" | jq '[.statusCheckRollup[] | select((.conclusion // "") != "SUCCESS" and (.name != "Block remove-before-merge paths") and (.name != "No remove-before-merge directories"))] | length')
[ "$BAD_CHECKS" -eq 0 ] || { printf '%s\n' "$PR_JSON" | jq '.statusCheckRollup'; echo "SHEPHERD FAILED: non-exempt checks are not successful."; exit 1; }
REVIEW=$(gh api "/repos/$REPO/pulls/$PR/reviews/$REVIEW_ID")
printf '%s' "$REVIEW" | jq -e --arg head "$EXPECTED_HEAD" '.commit_id == $head' >/dev/null
TOO_MANY=$(printf '%s' "$REVIEW" | jq 'select((.body // "") | test("was" + "n\\u0027t able to review"; "i")) | select((.body // "") | test("maximum number of files"; "i"))')
[ -z "$TOO_MANY" ] || { echo 'SHEPHERD FAILED: Copilot review refused due to maximum files.'; exit 1; }
TOP_LEVEL=$(gh api "/repos/$REPO/pulls/$PR/comments" | jq --argjson review_id "$REVIEW_ID" '[.[] | select(.pull_request_review_id == $review_id) | select(.in_reply_to_id == null)] | length')
[ "$TOP_LEVEL" -eq 0 ] || { echo "SHEPHERD FAILED: expected zero findings, found $TOP_LEVEL."; exit 1; }
printf 'FINAL_PR_STATE=%s\nCOPILOT_REVIEW_ID=%s\nTOP_LEVEL_FINDINGS=%s\n' "$(printf '%s' "$PR_JSON" | jq -c '{state,isDraft,baseRefName,headRefOid,mergeable,checks:[.statusCheckRollup[]|{name,conclusion}]}')" "$REVIEW_ID" "$TOP_LEVEL"","description":"Verify final PR gates","mode":"sync","initial_wait":120}

